package graph

import (
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/cplieger/deadset-go/v2/internal/facts"
)

func TestIndexNamesEveryGeneratedFileByItsHeaderLine(t *testing.T) {
	dir := t.TempDir()
	for name, body := range map[string]string{
		"go.mod":           "module example.com/app\n\ngo 1.27.1\n",
		"main.go":          "package main\n\nfunc main() { mocked(); colour() }\n",
		"main_test.go":     "package main\n\nimport \"testing\"\n\nfunc TestMain(t *testing.T) { mocked() }\n",
		"mock.go":          "// Code generated by MockGen. DO NOT EDIT.\n\npackage main\n\nfunc mocked() {}\n",
		"colour_string.go": "// Copyright the authors.\n\n// Code generated by \"stringer -type=Colour\"; DO NOT EDIT.\n\npackage main\n\nfunc colour() {}\n",
		"plain.go":         "// Code generated by hand, and edited.\n\npackage main\n",
	} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o600); err != nil {
			t.Fatalf("Setup: %v", err)
		}
	}
	result, root := loadDir(t, dir, "linux", "amd64")
	_, rs, err := inventoryOf(result, root, os.ReadFile)
	if err != nil {
		t.Fatalf("Setup: %v", err)
	}
	index, err := facts.NewIndex(result, rs)
	if err != nil {
		t.Fatalf("facts.NewIndex() error: %v", err)
	}

	type named struct {
		path, detail string
		line, site   int
	}
	var got []named
	for _, g := range index.Generated() {
		got = append(got, named{path: g.Path, detail: g.Detail, line: g.Line, site: g.Site.Line})
	}
	want := []named{
		{path: "colour_string.go", detail: `// Code generated by "stringer -type=Colour"; DO NOT EDIT.`, line: 3, site: 5},
		{path: "mock.go", detail: "// Code generated by MockGen. DO NOT EDIT.", line: 1, site: 3},
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Index.Generated() = %+v, want %+v", got, want)
	}
}
